  ('rostos_historia', 'person', 'neil-armstrong', 'Neil Armstrong', 'https://commons.wikimedia.org/wiki/Special:FilePath/Neil_Armstrong_pose.jpg?width=1200', 'Comandante da missão Apollo 11.', 'Antes de ser astronauta, foi piloto de testes de aviões experimentais.', '1930–2012', 'Exploração', 'Mundo', 'iniciante', '{"lifespan": "1930–2012", "birthplace": "Nasceu nos Estados Unidos", "field": "Exploração", "main_contribution": "Foi o primeiro ser humano a pisar na Lua, em 1969", "image_license": "Domínio público", "image_credit": null, "image_source": "https://commons.wikimedia.org/wiki/File:Neil_Armstrong_pose.jpg"}'),
