  ('santos-dumont', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Santos Dumont', '[{"text": "Nikola Tesla", "educational_note": "Nikola Tesla: desenvolveu o sistema de corrente alternada."}, {"text": "Alexander Graham Bell", "educational_note": "Alexander Graham Bell: patenteou o telefone."}, {"text": "Amelia Earhart", "educational_note": "Amelia Earhart: foi a primeira mulher a atravessar o Atlântico pilotando sozinha."}]', 'iniciante', 'Isso! É Santos Dumont (1873–1932).', 'É Santos Dumont (1873–1932). Pioneiro da aviação e um dos brasileiros mais famosos do mundo.', 'Popularizou o relógio de pulso: pediu ao amigo Louis Cartier um relógio que pudesse usar enquanto pilotava.', 'Foi inventor e aviador.', 'Viveu entre 1873 e 1932.', 'Nasceu no Brasil, em Minas Gerais.', NULL),
  ('santos-dumont', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Santos Dumont?', 'Voou com o 14-bis em Paris, em 1906', '[{"text": "Desenvolveu a lâmpada incandescente prática e o fonógrafo", "educational_note": "Essa foi a contribuição de Thomas Edison."}, {"text": "Desenvolveu o sistema de corrente alternada", "educational_note": "Essa foi a contribuição de Nikola Tesla."}, {"text": "Patenteou o telefone", "educational_note": "Essa foi a contribuição de Alexander Graham Bell."}]', 'iniciante', 'Isso! Santos Dumont voou com o 14-bis em Paris, em 1906.', 'Santos Dumont voou com o 14-bis em Paris, em 1906.', 'Popularizou o relógio de pulso: pediu ao amigo Louis Cartier um relógio que pudesse usar enquanto pilotava.', NULL, NULL, NULL, NULL),
  ('machado-de-assis', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Machado de Assis', '[{"text": "Jane Austen", "educational_note": "Jane Austen: escreveu Orgulho e Preconceito."}, {"text": "William Shakespeare", "educational_note": "William Shakespeare: escreveu Romeu e Julieta e Hamlet."}, {"text": "Castro Alves", "educational_note": "Castro Alves: escreveu ''O Navio Negreiro'', poema contra a escravidão."}]', 'iniciante', 'Isso! É Machado de Assis (1839–1908).', 'É Machado de Assis (1839–1908). Considerado o maior escritor da literatura brasileira.', 'Foi o primeiro presidente da Academia Brasileira de Letras, fundada em 1897.', 'Foi escritor.', 'Viveu entre 1839 e 1908.', 'Nasceu no Brasil, no Rio de Janeiro.', NULL),
  ('machado-de-assis', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Machado de Assis?', 'Escreveu Dom Casmurro e Memórias Póstumas de Brás Cubas', '[{"text": "Escreveu Orgulho e Preconceito", "educational_note": "Essa foi a contribuição de Jane Austen."}, {"text": "Escreveu Romeu e Julieta e Hamlet", "educational_note": "Essa foi a contribuição de William Shakespeare."}, {"text": "Escreveu ''O Navio Negreiro'', poema contra a escravidão", "educational_note": "Essa foi a contribuição de Castro Alves."}]', 'iniciante', 'Isso! Machado de Assis escreveu Dom Casmurro e Memórias Póstumas de Brás Cubas.', 'Machado de Assis escreveu Dom Casmurro e Memórias Póstumas de Brás Cubas.', 'Foi o primeiro presidente da Academia Brasileira de Letras, fundada em 1897.', NULL, NULL, NULL, NULL),
  ('dom-pedro-i', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Dom Pedro I', '[{"text": "Dom Pedro II", "educational_note": "Dom Pedro II: governou o Brasil como imperador por quase 50 anos."}, {"text": "Rui Barbosa", "educational_note": "Rui Barbosa: ajudou a redigir a primeira Constituição da República, de 1891."}, {"text": "Winston Churchill", "educational_note": "Winston Churchill: liderou o Reino Unido na Segunda Guerra Mundial."}]', 'intermediario', 'Isso! É Dom Pedro I (1798–1834).', 'É Dom Pedro I (1798–1834). Primeiro imperador do Brasil.', 'Depois de deixar o Brasil, voltou a Portugal e foi rei de lá com o nome de Dom Pedro IV.', 'Foi governante.', 'Viveu entre 1798 e 1834.', 'Nasceu em Portugal, em Queluz.', NULL),
  ('dom-pedro-i', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Dom Pedro I?', 'Proclamou a Independência do Brasil em 1822', '[{"text": "Criou a CLT, a Consolidação das Leis do Trabalho", "educational_note": "Essa foi a contribuição de Getúlio Vargas."}, {"text": "Reinou no Reino Unido por 63 anos", "educational_note": "Essa foi a contribuição de Rainha Vitória."}, {"text": "Assinou a Lei Áurea, que aboliu a escravidão em 1888", "educational_note": "Essa foi a contribuição de Princesa Isabel."}]', 'intermediario', 'Isso! Dom Pedro I proclamou a Independência do Brasil em 1822.', 'Dom Pedro I proclamou a Independência do Brasil em 1822.', 'Depois de deixar o Brasil, voltou a Portugal e foi rei de lá com o nome de Dom Pedro IV.', NULL, NULL, NULL, NULL),
