  ('dom-pedro-ii', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Dom Pedro II?', 'Governou o Brasil como imperador por quase 50 anos', '[{"text": "Reinou no Reino Unido por 63 anos", "educational_note": "Essa foi a contribuição de Rainha Vitória."}, {"text": "Proclamou a Independência do Brasil em 1822", "educational_note": "Essa foi a contribuição de Dom Pedro I."}, {"text": "Criou a CLT, a Consolidação das Leis do Trabalho", "educational_note": "Essa foi a contribuição de Getúlio Vargas."}]', 'intermediario', 'Isso! Dom Pedro II governou o Brasil como imperador por quase 50 anos.', 'Dom Pedro II governou o Brasil como imperador por quase 50 anos.', 'Conheceu o telefone de Graham Bell na Exposição de Filadélfia, em 1876.', NULL, NULL, NULL, NULL),
  ('princesa-isabel', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Princesa Isabel', '[{"text": "Dom Pedro II", "educational_note": "Dom Pedro II: governou o Brasil como imperador por quase 50 anos."}, {"text": "José Bonifácio", "educational_note": "José Bonifácio: articulou a Independência do Brasil."}, {"text": "Napoleão Bonaparte", "educational_note": "Napoleão Bonaparte: tornou-se imperador da França e criou o Código Civil."}]', 'iniciante', 'Isso! É Princesa Isabel (1846–1921).', 'É Princesa Isabel (1846–1921). Filha de Dom Pedro II e herdeira do trono imperial.', 'Governou o Brasil como regente três vezes, durante viagens do pai ao exterior.', 'Foi governante.', 'Viveu entre 1846 e 1921.', 'Nasceu no Brasil, no Rio de Janeiro.', NULL),
  ('princesa-isabel', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Princesa Isabel?', 'Assinou a Lei Áurea, que aboliu a escravidão em 1888', '[{"text": "Reinou no Reino Unido por 63 anos", "educational_note": "Essa foi a contribuição de Rainha Vitória."}, {"text": "Ajudou a redigir a primeira Constituição da República, de 1891", "educational_note": "Essa foi a contribuição de Rui Barbosa."}, {"text": "Liderou o Reino Unido na Segunda Guerra Mundial", "educational_note": "Essa foi a contribuição de Winston Churchill."}]', 'iniciante', 'Isso! Princesa Isabel assinou a Lei Áurea, que aboliu a escravidão em 1888.', 'Princesa Isabel assinou a Lei Áurea, que aboliu a escravidão em 1888.', 'Governou o Brasil como regente três vezes, durante viagens do pai ao exterior.', NULL, NULL, NULL, NULL),
