  ('neil-armstrong', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Neil Armstrong', '[{"text": "Cândido Rondon", "educational_note": "Cândido Rondon: levou linhas de telégrafo ao interior e defendeu os povos indígenas."}, {"text": "Frederick Douglass", "educational_note": "Frederick Douglass: fugiu da escravidão e virou um dos maiores líderes abolicionistas."}, {"text": "Charlie Chaplin", "educational_note": "Charlie Chaplin: criou o personagem Carlitos, o vagabundo."}]', 'iniciante', 'Isso! É Neil Armstrong (1930–2012).', 'É Neil Armstrong (1930–2012). Comandante da missão Apollo 11.', 'Antes de ser astronauta, foi piloto de testes de aviões experimentais.', 'Foi astronauta.', 'Viveu entre 1930 e 2012.', 'Nasceu nos Estados Unidos.', NULL),
  ('neil-armstrong', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Neil Armstrong?', 'Foi o primeiro ser humano a pisar na Lua, em 1969', '[{"text": "Levou linhas de telégrafo ao interior e defendeu os povos indígenas", "educational_note": "Essa foi a contribuição de Cândido Rondon."}, {"text": "Fugiu da escravidão e virou um dos maiores líderes abolicionistas", "educational_note": "Essa foi a contribuição de Frederick Douglass."}, {"text": "Compôs mais de 600 obras, como a ópera A Flauta Mágica", "educational_note": "Essa foi a contribuição de Wolfgang Amadeus Mozart."}]', 'iniciante', 'Isso! Neil Armstrong foi o primeiro ser humano a pisar na Lua, em 1969.', 'Neil Armstrong foi o primeiro ser humano a pisar na Lua, em 1969.', 'Antes de ser astronauta, foi piloto de testes de aviões experimentais.', NULL, NULL, NULL, NULL),
  ('stephen-hawking', 'rostos_historia', 'identify_person', 'Quem é esta pessoa?', 'Stephen Hawking', '[{"text": "Isaac Newton", "educational_note": "Isaac Newton: formulou as leis do movimento e a gravitação universal."}, {"text": "Charles Darwin", "educational_note": "Charles Darwin: propôs a teoria da evolução por seleção natural."}, {"text": "Marie Curie", "educational_note": "Marie Curie: pesquisou a radioatividade e descobriu o polônio e o rádio."}]', 'intermediario', 'Isso! É Stephen Hawking (1942–2018).', 'É Stephen Hawking (1942–2018). Um dos físicos mais conhecidos do nosso tempo.', 'Escreveu o best-seller ''Uma Breve História do Tempo'', de 1988.', 'Foi cientista, na física teórica.', 'Viveu entre 1942 e 2018.', 'Nasceu na Inglaterra.', NULL),
  ('stephen-hawking', 'rostos_historia', 'identify_contribution', 'Qual foi a principal contribuição de Stephen Hawking?', 'Estudou buracos negros e a origem do universo', '[{"text": "Criou a psicanálise", "educational_note": "Essa foi a contribuição de Sigmund Freud."}, {"text": "Pesquisou a radioatividade e descobriu o polônio e o rádio", "educational_note": "Essa foi a contribuição de Marie Curie."}, {"text": "Escreveu o primeiro algoritmo para uma máquina de calcular", "educational_note": "Essa foi a contribuição de Ada Lovelace."}]', 'intermediario', 'Isso! Stephen Hawking estudou buracos negros e a origem do universo.', 'Stephen Hawking estudou buracos negros e a origem do universo.', 'Escreveu o best-seller ''Uma Breve História do Tempo'', de 1988.', NULL, NULL, NULL, NULL)
) AS v(content_slug, game_slug, question_type, prompt_text, correct_answer, distractors, difficulty, feedback_correct, feedback_incorrect, curiosity_fact, hint_1, hint_2, hint_3, image_override)
JOIN public.visual_content c ON c.slug = v.content_slug
